<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRolesVO;

trait ClientIdentityRolesAttributeHolder
{
    protected ClientIdentityRolesVO|string|null $roles = null;
    protected bool $rolesAssigned = false;

    public function getRolesOrDefault(?ClientIdentityRolesVO $roles): ?ClientIdentityRolesVO
    {
        return $this->rolesAssigned ? ($this->roles !== null ? ClientIdentityRolesVO::from($this->roles) : null) : $roles;
    }
    public function roles(ClientIdentityRolesVO|string|null $roles): static
    {
        $this->roles = $roles;
        $this->rolesAssigned = true;
        return $this;
    }
    public function getRoles(): ?string
    {
        return $this->roles instanceof ClientIdentityRolesVO ? $this->roles->value() : $this->roles;
    }
    public function isRolesAssigned(): bool
    {
        return $this->rolesAssigned;
    }
    public function writeRolesTo(mixed $att): void
    {
        if ($this->rolesAssigned) {
            $att->roles($this->roles);
        }
    }
    public function readRolesFrom(mixed $att): void
    {
        if ($att->isRolesAssigned()) {
            $roles = $att->getRoles();
            $this->roles($roles);
        }
    }
    public function unsetRoles(): static
    {
        $this->rolesAssigned = false;
        return $this;
    }
    protected function withDefaultRoles(): void
    {
    }
    protected function withAssertedRolesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rolesAssigned = $this->rolesAssigned) {
            $value->roles = ClientIdentityRolesVO::tryFrom($this->roles, $errorsList);
        }
    }
}
